def add_page(self, title=None, content=None, old_url=None,
                 tags=None, old_id=None, old_parent_id=None):
        """
        Adds a page to the list of pages to be imported - used by the
        Wordpress importer.
        """
        if old_url is None:
            old_url = ''
        if old_id is None:
            old_id = ''
        if old_parent_id is None:
            old_parent_id = ''
        if tags is None:
            tags = []
        if content is None:
            content = ''
        if title is None:
            title = ''
        self.pages.append({
            'title': title,
            'content': content,
            'old_url': old_url,
            'tags': tags,
            'old_id': old_id,
            'old_parent_id': old_parent_id,
        })

